def run(b,name):
 c,p,e,prefix=t.setup(b,name);t.organize(p);handles=t.card(p).locator('.master-category-meal>.organize-drag-handle');assert handles.count()==11;assert not p.locator('.master-category-header>.organize-drag-handle').count();assert t.row(p,100).locator('.organize-row-status').count()==1
